{
  "name": "@sightspool/sdk",
  "version": "0.5.0",
  "description": "Sightspool research SDK \u2014 invite website visitors and signed-in users into approved user research.",
  "type": "module",
  "main": "./dist/index.cjs",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "require": "./dist/index.cjs"
    }
  },
  "files": [
    "dist",
